    'panel.simple': 'Widok prosty', 'note.tonightLink': 'Gdzie jest dziś w nocy? →', 'story.next': 'Następny', 'rg.hook.barnard': 'gwiazda, której miejsce na niebie zmienia się najszybciej', 'rg.hook.epsindib': 'dwa brązowe karły krążące wokół pobliskiej gwiazdy', 'res.sig': 'Pewność (wielokrotność błędu pomiaru)', 'rg.offer': 'Nie wiesz, od czego zacząć? Przewodnik w minutę obejrzy z tobą jedną gwiazdę.', 'rg.offerGo': 'Uruchom przewodnik', 'rg.offerNo': 'Rozejrzę się sam', 'story.bright.h': 'Zbyt jasna, by ją zmierzyć', 'story.bright.p': 'Ta gwiazda oślepia kamerę SPHEREx: środek jej obrazu jest całkiem biały, więc nie da się tu zmierzyć ani jej ruchu, ani jasności.', 'story.faint.h': 'Zbyt słaba, by ją zmierzyć', 'story.faint.p': 'W pierścieniu jest za mało światła, by stwierdzić, czy coś się poruszyło lub zmieniło.', 'story.calm.h': 'Nic się nie zmieniło', 'story.calm.p': 'Ani się nie poruszył, ani nie zmienił jasności. Większość obiektów na niebie taka jest; te, które się zmieniają, są rzadkie i dlatego ciekawe.', 'story.seeChange': 'Zobacz taki, który się zmienia: {name} →', 'story.flagged': '<b>Coś w pobliżu się wyróżnia.</b> Na obrazie jest oznaczone żółtym ◇; dotknij go, aby mu się przyjrzeć.', 'rg.close': 'Zamknij przewodnik', 'rg.skip': 'Pomiń ten krok', 'rg.did': 'Gotowe', 'rg.r1': 'Ta mapa to całe niebo. Teleskop SPHEREx NASA sfotografował je w podczerwieni, której nasze oczy nie widzą.', 'rg.r1.do': 'Przesuń mapę albo ją przybliż.', 'rg.r2': 'SPHEREx sfotografował niebo w 102 osobnych barwach podczerwieni. Pasek na dole wybiera jedną z nich.', 'rg.r2.do': 'Przesuń pasek i zobacz, jak zmienia się niebo.', 'rg.r3': 'Gwiazda w tej ramce to Gwiazda Barnarda: gwiazda, której miejsce na niebie zmienia się najszybciej.', 'rg.r3.do': 'Dotknij wnętrza ramki.', 'rg.r4': 'SPHEREx sfotografował tę gwiazdę w różnych chwilach. Gwiazda w pierścieniu za każdym razem przesuwa się trochę w górę.', 'rg.r4.do': 'Przeglądaj zdjęcia strzałkami ‹ i ›.', 'rg.r5': 'Strona zmierzyła to sama: jak daleko i w którą stronę przesuwa się gwiazda.', 'rg.r6': 'Są też starsze zdjęcia tej gwiazdy: od 2000 roku, z trzech teleskopów.', 'rg.r6.do': 'Naciśnij „Obejrzyj”.', 'rg.r7': 'Teraz mija 26 lat. Gwiazda przebywa na niebie długą drogę; gwiazdy wokół zostają na miejscu.', 'rg.r8': 'Wszystkie liczby, wykresy i pliki do pobrania są w zakładce Dane, dla tych, którzy przychodzą badać.', 'rg.r8.do': 'Dotknij Dane.', 'rg.r9': 'Każda liczba ma obok swoją nazwę: szacunek tej strony i jego margines, wartość astronomów, gwiazdy porównawcze. „Cytuj” kopiuje odnośnik.', 'rg.r10': 'Twoja kolej. Dotknij dowolnej gwiazdy na mapie albo otwórz jedną z tych:', 'rg.hook.rwaur': 'pociemniała w ciągu roku', 'rg.hook.wise0855': 'najzimniejszy znany brązowy karzeł', 'rg.hook.rdra': 'olbrzym, który jaśnieje i blednie', 'res.est': 'Szacunek tej strony', 'res.catv': 'Wartość astronomów (katalog)', 'res.dir': 'Kierunek', 'res.dets': 'Zmierzono w detektorach', 'res.det': 'Detektor (długość fali)', 'res.place': 'Jego położenie, {a} → {b}', 'res.within': 'to samo z dokładnością do {v}', 'res.compStars': 'Zwykłe gwiazdy na tych samych obrazach', 'res.minMove': 'Najmniejszy ruch widoczny tutaj', 'res.vs1': 'Jasność przy każdej wizycie względem pierwszej', 'res.varied': 'zmieniły się najwyżej o {v}', 'res.substances': 'Substancje, których ślady widać, i gdzie', 'res.dimmed': 'o {v} mniej światła', 'res.brighter': 'o {v} więcej światła: świecący gaz', 'res.why': 'Dlaczego ślad: każda substancja pochłania światło tylko w swoim paśmie długości fal, więc tam światło jest słabsze. Ślad to mocna wskazówka, nie dowód.', 'res.bandsChecked': 'Sprawdzone pasma', 'res.noSub': 'Brak śladu jakiejkolwiek substancji', 'res.frames': 'Przejrzane ekspozycje', 'res.units': '″ sekunda łuku: maleńki kąt na niebie (tarcza Księżyca ma 1800″) · µm mikrometr: długość fali światła · D1–D6: sześć detektorów SPHEREx, każdy dla jednego pasma fal', 'res.title': 'Wyniki', 'res.motion': 'Ruch', 'res.change': 'Jasność', 'res.bands': 'Pasma cząsteczek', 'res.movers': 'Przelatujące ciała', 'cite.btn': 'Cytuj', 'cite.copied': 'Skopiowano odnośnik: strona, data i pokazane dane.', 'cite.accessed': 'dostęp', 'cite.data': 'Dane', 'story.what': 'Co się stało?', 'story.else': 'Co jeszcze sprawdzono?', 'story.checked': 'Co sprawdzono?', 'story.ring': 'W pierścieniu', 'story.real': 'Prawdziwa zmiana: gwiazdy obok pozostały takie same', 'ans.yes': 'Tak', 'ans.no': 'Nie', 'ans.maybe': 'Może', 'mode.epochs': 'co 6 miesięcy', 'mode.frames': 'pojedynczo', 'mode.color': 'ruch widać w kolorze', 'mode.diff': 'co się zmieniło?', 'mode.bands': '6 barw podczerwieni', 'mode.deep': 'wszystkie nałożone, najostrzej', 'mode.trail': 'przystanek po przystanku', 'years.watch': 'Obejrzyj: {a} → {b}', 'years.over': 'to miejsce, {a} → {b}, trzy teleskopy', 'years.went': 'Przesunięcie o {d} na {dir}', 'years.moon': 'W porównaniu z szerokością tarczy Księżyca: {p}%', 'years.mine': 'Szacunek tej strony ({n} obrazów)', 'years.cat': 'Wartość astronomów (katalog), ta wiarygodna', 'years.off': 'Średnia odległość jego światła od miejsca z katalogu', 'years.rate': '{v} rocznie', 'tel.2MASS': 'teleskopy naziemne, USA i Chile', 'tel.WISE': 'teleskop kosmiczny NASA', 'tel.NEOWISE': 'ten sam teleskop, kolejne lata', 'tel.SPHEREx': 'teleskop kosmiczny NASA, od 2025', 'quiz.motion': 'Czy się poruszył?', 'quiz.change': 'Czy zmieniła się jego jasność?', 'quiz.bands': 'Czy w jego świetle widać cząsteczki?', 'quiz.movers': 'Czy coś przeleciało?', 'quiz.proof': 'Dowód', 'loupe.hint': 'Wskazówka: przytrzymaj palec na mapie, by zobaczyć lupę', 'panel.tabSummary': 'Historia', 'panel.tabAll': 'Dane', 'panel.factsShort': 'Fakty', 'coach.openShort': 'Jak czytać', 'nav.activities': 'Aktywności', 'nav.guide': 'Przewodnik',
